grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.tutor_payout_settings(tutor_id uuid primary key references app_private.tutors(id),enabled_channels text[] not null default '{}',version integer not null default 1,updated_by uuid references app_private.accounts(id),updated_at timestamptz not null default now(),check(enabled_channels<@array['instapay','vodafone_cash']::text[]));
create table finance_private.payout_destinations(id uuid primary key,tutor_id uuid not null references app_private.tutors(id),owner_account_id uuid not null references app_private.accounts(id),channel text not null check(channel in('instapay','vodafone_cash')),identifier_version integer not null default 1 check(identifier_version=1),encrypted_identifier jsonb not null,masked_identifier text not null,identifier_fingerprint text not null,ciphertext_digest text not null,payee_name text not null,verification_status text not null default 'unverified' check(verification_status in('unverified','verified','rejected')),proposed_by uuid not null references app_private.accounts(id),propose_idempotency_key text not null,propose_request jsonb not null,version integer not null default 1,created_at timestamptz not null default now(),unique(proposed_by,propose_idempotency_key));
create table finance_private.payout_destination_artifacts(id uuid primary key default gen_random_uuid(),actor_account_id uuid not null references app_private.accounts(id),auth_session_id uuid not null,destination_id uuid not null references finance_private.payout_destinations(id),destination_version integer not null,ciphertext_digest text not null,approval_request jsonb not null,approval_request_hash text not null,expires_at timestamptz not null,consumed_at timestamptz,consumed_command_id uuid,created_at timestamptz not null default now());
create table finance_private.payout_destination_versions(id uuid primary key default gen_random_uuid(),destination_id uuid not null unique references finance_private.payout_destinations(id),tutor_id uuid not null references app_private.tutors(id),owner_account_id uuid not null references app_private.accounts(id),channel text not null,encrypted_identifier jsonb not null,masked_identifier text not null,identifier_fingerprint text not null,ciphertext_digest text not null,evidence_file_id uuid not null references app_private.files(id),verified_by uuid not null references app_private.accounts(id),validation_artifact_id uuid not null unique references finance_private.payout_destination_artifacts(id),verified_at timestamptz not null default now());
create table finance_private.payout_attempts(id uuid primary key default gen_random_uuid(),tutor_id uuid not null references app_private.tutors(id),destination_version_id uuid not null references finance_private.payout_destination_versions(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),state text not null default 'pending' check(state in('draft','pending','settled','failed','unknown','reversed')),version integer not null default 1,retry_of_attempt_id uuid unique references finance_private.payout_attempts(id),authorized_by uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now());
create table finance_private.payout_allocations(id uuid primary key default gen_random_uuid(),payout_attempt_id uuid not null references finance_private.payout_attempts(id),earning_id uuid not null references finance_private.tutor_earnings(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),created_at timestamptz not null default now(),unique(payout_attempt_id,earning_id));
create table finance_private.payout_outcomes(id uuid primary key default gen_random_uuid(),payout_attempt_id uuid not null references finance_private.payout_attempts(id),outcome text not null check(outcome in('settled','failed','unknown')),receiving_account_id uuid references finance_private.receiving_accounts(id),external_reference text not null,evidence_file_id uuid not null references app_private.files(id),settled_at timestamptz,ledger_transaction_id uuid references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,recorded_at timestamptz not null default now());
create unique index payout_once_settled on finance_private.payout_outcomes(payout_attempt_id) where outcome='settled';
create table finance_private.payout_reversals(id uuid primary key default gen_random_uuid(),payout_attempt_id uuid not null references finance_private.payout_attempts(id),amount_minor bigint not null check(amount_minor>0),receiving_account_id uuid not null references finance_private.receiving_accounts(id),external_reference text not null,evidence_file_id uuid not null references app_private.files(id),effective_at timestamptz not null,reason text not null,ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now(),unique(receiving_account_id,external_reference));
create table finance_private.payout_reversal_allocations(reversal_id uuid not null references finance_private.payout_reversals(id),payout_allocation_id uuid not null references finance_private.payout_allocations(id),amount_minor bigint not null check(amount_minor>0),primary key(reversal_id,payout_allocation_id));
create function app_private.payroll_immutable()returns trigger language plpgsql set search_path='' as $$declare allowed text[];begin if tg_op='DELETE'then raise exception'IMMUTABLE_VERSION';end if;allowed:=case tg_table_name when'payout_attempts'then array['state','version'] when'payout_destinations'then array['verification_status','version'] when'payout_destination_artifacts'then array['consumed_at','consumed_command_id'] when'tutor_payout_settings'then array['enabled_channels','version','updated_by','updated_at'] else '{}'::text[]end;if(to_jsonb(old)-allowed)is distinct from(to_jsonb(new)-allowed)or(tg_table_name='payout_destination_artifacts'and to_jsonb(old)->>'consumed_at' is not null)then raise exception'IMMUTABLE_VERSION';end if;return new;end$$;
do $$declare n text;begin foreach n in array array['tutor_payout_settings','payout_destinations','payout_destination_artifacts','payout_destination_versions','payout_attempts','payout_allocations','payout_outcomes','payout_reversals','payout_reversal_allocations']loop execute format('alter table finance_private.%I enable row level security',n);execute format('revoke all on finance_private.%I from public,anon,authenticated,service_role,git_tutor_worker',n);execute format('grant select,insert on finance_private.%I to git_tutor_commands',n);execute format('create policy payroll_commands on finance_private.%I to git_tutor_commands using(true)with check(true)',n);if n=any(array['tutor_payout_settings','payout_destinations','payout_destination_artifacts','payout_attempts'])then execute format('grant update on finance_private.%I to git_tutor_commands',n);execute format('create trigger immutable_payroll_source before update or delete on finance_private.%I for each row execute function app_private.payroll_immutable()',n);else execute format('create trigger immutable_payroll_history before update or delete on finance_private.%I for each row execute function app_private.reject_immutable_change()',n);end if;end loop;end$$;

create function app_private.payroll_assert_scope(p_actor uuid,p_tutor uuid default null)returns uuid language plpgsql security definer set search_path='' as $$declare tutor uuid;begin if app_private.has_role(p_actor,'admin')then perform app_private.require_role(p_actor,'admin');if p_tutor is null then raise exception'VALIDATION_ERROR';end if;select id into tutor from app_private.tutors where id=p_tutor;else perform app_private.require_role(p_actor,'tutor');select id into tutor from app_private.tutors where account_id=p_actor and(p_tutor is null or id=p_tutor);end if;if tutor is null then raise exception'NOT_FOUND';end if;return tutor;end$$;
create function finance_private.payroll_earning_balance(p_earning uuid,p_as_of timestamptz default now())returns jsonb language plpgsql stable security definer set search_path='' as $$declare e finance_private.tutor_earnings%rowtype;adjustment numeric;paid numeric;returned numeric;reserved numeric;owed numeric;v integer;begin select * into e from finance_private.tutor_earnings where id=p_earning and posted_at<=p_as_of;if e.id is null then raise exception'NOT_FOUND';end if;
 select coalesce(sum(delta_minor),0),count(*)+1 into adjustment,v from finance_private.earning_adjustments where earning_id=e.id and posted_at<=p_as_of;
 select coalesce(sum(a.amount_minor),0)into paid from finance_private.payout_allocations a join finance_private.payout_outcomes o on o.payout_attempt_id=a.payout_attempt_id and o.outcome='settled' where a.earning_id=e.id and o.recorded_at<=p_as_of;
 select coalesce(sum(a.amount_minor),0)into returned from finance_private.payout_reversal_allocations a join finance_private.payout_allocations x on x.id=a.payout_allocation_id join finance_private.payout_reversals r on r.id=a.reversal_id where x.earning_id=e.id and r.created_at<=p_as_of;
 select coalesce(sum(a.amount_minor),0)into reserved from finance_private.payout_allocations a join finance_private.payout_attempts p on p.id=a.payout_attempt_id where a.earning_id=e.id and p.created_at<=p_as_of and coalesce((select outcome from finance_private.payout_outcomes where payout_attempt_id=p.id and recorded_at<=p_as_of order by recorded_at desc,id desc limit 1),'pending')in('pending','unknown');owed:=e.amount_minor+adjustment-paid+returned;
 return jsonb_build_object('earning_id',e.id,'occurrence_id',e.occurrence_id,'source_type',e.source_type,'amount_minor',e.amount_minor,'adjustment_minor',finance_private.finance_safe_total(adjustment),'net_minor',finance_private.finance_safe_total(e.amount_minor+adjustment),'owed_minor',finance_private.finance_safe_total(owed),'reserved_minor',finance_private.finance_safe_total(reserved),'available_minor',finance_private.finance_safe_total(greatest(owed-reserved,0)),'version',v,'effective_at',e.effective_at,'posted_at',e.posted_at);end$$;
create function finance_private.payroll_statement(p_tutor uuid,p_as_of timestamptz default now())returns jsonb language plpgsql stable security definer set search_path='' as $$declare earned numeric:=0;owed numeric:=0;reserved numeric:=0;b jsonb;name text;begin if p_as_of is null or not isfinite(p_as_of)or p_as_of>now()+interval'5 seconds'or p_as_of<timestamptz'0001-01-01+00'then raise exception'INVALID_TIME';end if;for b in select finance_private.payroll_earning_balance(id,p_as_of)from finance_private.tutor_earnings where tutor_id=p_tutor and posted_at<=p_as_of loop earned:=earned+(b->>'net_minor')::numeric;owed:=owed+(b->>'owed_minor')::numeric;reserved:=reserved+(b->>'reserved_minor')::numeric;end loop;select coalesce(p.display_name,'Tutor')into name from app_private.tutors t left join app_private.tutor_profile_versions p on p.id=t.approved_profile_version_id where t.id=p_tutor;return jsonb_build_object('tutor_id',p_tutor,'display_name',name,'currency','EGP','as_of',p_as_of,'earned_minor',finance_private.finance_safe_total(earned),'settled_minor',finance_private.finance_safe_total(earned-owed),'owed_minor',finance_private.finance_safe_total(owed),'reserved_minor',finance_private.finance_safe_total(reserved),'available_minor',finance_private.finance_safe_total(greatest(owed-reserved,0)),'recovery_minor',finance_private.finance_safe_total(greatest(-owed,0)));end$$;
create function app_private.payroll_destination_dto(p_id uuid)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('destination_id',d.id,'tutor_id',d.tutor_id,'channel',d.channel,'masked_identifier',d.masked_identifier,'payee_name',d.payee_name,'verification_status',d.verification_status,'verified_version_id',(select id from finance_private.payout_destination_versions where destination_id=d.id),'version',d.version,'created_at',d.created_at)from finance_private.payout_destinations d where d.id=p_id$$;
create function app_private.payroll_attempt_dto(p_id uuid,p_admin boolean)returns jsonb language plpgsql stable security definer set search_path='' as $$declare p finance_private.payout_attempts%rowtype;d finance_private.payout_destination_versions%rowtype;o finance_private.payout_outcomes%rowtype;returned bigint;begin select * into p from finance_private.payout_attempts where id=p_id;select * into d from finance_private.payout_destination_versions where id=p.destination_version_id;select * into o from finance_private.payout_outcomes where payout_attempt_id=p.id and outcome='settled';select coalesce(sum(amount_minor),0)into returned from finance_private.payout_reversals where payout_attempt_id=p.id;return jsonb_build_object('payout_attempt_id',p.id,'tutor_id',p.tutor_id,'destination_id',d.destination_id,'destination_version_id',d.id,'channel',d.channel,'masked_identifier',d.masked_identifier,'amount_minor',p.amount_minor,'returned_minor',returned,'state',p.state,'version',p.version,'receiving_account_id',o.receiving_account_id,'external_reference',o.external_reference,'settled_at',o.settled_at,'retry_of_attempt_id',p.retry_of_attempt_id,'allocations',(select jsonb_agg(jsonb_build_object('earning_id',earning_id,'amount_minor',amount_minor)order by earning_id)from finance_private.payout_allocations where payout_attempt_id=p.id),'can_reconcile',p_admin and p.state in('pending','unknown'),'can_retry',p_admin and p.state='failed'and not exists(select 1 from finance_private.payout_attempts where retry_of_attempt_id=p.id),'can_reverse',p_admin and p.state='settled'and returned<p.amount_minor,'created_at',p.created_at);end$$;
create function api.get_tutor_statement(p_tutor_id uuid default null,p_as_of timestamptz default now())returns jsonb language sql security definer set search_path='' as $$select finance_private.payroll_statement(app_private.payroll_assert_scope(app_private.require_actor(),p_tutor_id),p_as_of)$$;
create function app_private.payroll_list(p_kind text,p_tutor uuid,p_cursor text,p_limit integer)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();tutor uuid;rows jsonb;after_at timestamptz;after_id uuid;begin if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 if p_kind='tutors'then perform app_private.require_role(actor,'admin');select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('tutor_id',x.id,'display_name',coalesce(x.display_name,'Tutor'),'version',coalesce(x.version,1),'enabled_channels',coalesce(x.enabled_channels,'{}')))order by x.created_at desc,x.id desc),'[]')into rows from(select t.id,t.created_at,p.display_name,s.version,s.enabled_channels from app_private.tutors t left join app_private.tutor_profile_versions p on p.id=t.approved_profile_version_id left join finance_private.tutor_payout_settings s on s.tutor_id=t.id where(p_cursor is null or(t.created_at,t.id)<(after_at,after_id))order by t.created_at desc,t.id desc limit p_limit+1)x;
 else tutor:=app_private.payroll_assert_scope(actor,p_tutor);if p_kind='earnings'then select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.posted_at,'data',finance_private.payroll_earning_balance(x.id))order by x.posted_at desc,x.id desc),'[]')into rows from(select e.*from finance_private.tutor_earnings e where e.tutor_id=tutor and(p_cursor is null or(e.posted_at,e.id)<(after_at,after_id))order by e.posted_at desc,e.id desc limit p_limit+1)x;
 elsif p_kind='destinations'then select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payroll_destination_dto(x.id))order by x.created_at desc,x.id desc),'[]')into rows from(select d.*from finance_private.payout_destinations d where d.tutor_id=tutor and(p_cursor is null or(d.created_at,d.id)<(after_at,after_id))order by d.created_at desc,d.id desc limit p_limit+1)x;
 elsif p_kind='payouts'then select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payroll_attempt_dto(x.id,app_private.has_role(actor,'admin')))order by x.created_at desc,x.id desc),'[]')into rows from(select p.*from finance_private.payout_attempts p where p.tutor_id=tutor and(p_cursor is null or(p.created_at,p.id)<(after_at,after_id))order by p.created_at desc,p.id desc limit p_limit+1)x;else raise exception'VALIDATION_ERROR';end if;end if;return app_private.package_page(rows,p_limit);end$$;
create function api.list_tutor_earnings(p_tutor_id uuid default null,p_cursor text default null,p_limit integer default 25)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_list('earnings',p_tutor_id,p_cursor,p_limit)$$;
create function api.list_payout_destinations(p_tutor_id uuid default null,p_cursor text default null,p_limit integer default 25)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_list('destinations',p_tutor_id,p_cursor,p_limit)$$;
create function api.list_payouts(p_tutor_id uuid default null,p_cursor text default null,p_limit integer default 25)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_list('payouts',p_tutor_id,p_cursor,p_limit)$$;
create function api.list_payout_tutors(p_cursor text default null,p_limit integer default 25)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_list('tutors',null,p_cursor,p_limit)$$;

create function api.set_tutor_payout_methods(p_tutor_id uuid,p_channels text[],p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=''as $$declare actor uuid:=app_private.require_actor();ctx jsonb;s finance_private.tutor_payout_settings%rowtype;begin perform app_private.require_role(actor,'admin');perform app_private.payroll_assert_scope(actor,p_tutor_id);ctx:=app_private.booking_begin(actor,'set_tutor_payout_methods',jsonb_build_object('tutor_id',p_tutor_id,'channels',p_channels,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'then return ctx->'replay_result';end if;perform 1 from app_private.tutors where id=p_tutor_id for update;insert into finance_private.tutor_payout_settings(tutor_id)values(p_tutor_id)on conflict do nothing;select *into s from finance_private.tutor_payout_settings where tutor_id=p_tutor_id for update;if p_expected_version is distinct from s.version then raise exception'VERSION_CONFLICT';end if;if p_channels is null or cardinality(p_channels)>2 or exists(select 1 from unnest(p_channels)x where x is null or x not in('instapay','vodafone_cash'))or cardinality(p_channels)<>(select count(distinct x)from unnest(p_channels)x)then raise exception'VALIDATION_ERROR';end if;update finance_private.tutor_payout_settings set enabled_channels=p_channels,version=s.version+1,updated_by=actor,updated_at=now()where tutor_id=p_tutor_id;return app_private.booking_finish(ctx,p_tutor_id,s.version+1,jsonb_build_object('enabled_channels',p_channels),'payout_methods_updated',jsonb_build_object('tutor_id',p_tutor_id));end$$;
create function app_private.prepare_payout_destination(p_actor_account_id uuid,p_auth_session_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=''as $$declare tutor uuid;prior jsonb;begin perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id,false);perform app_private.require_role(p_actor_account_id,'tutor');select id into tutor from app_private.tutors where account_id=p_actor_account_id;if tutor is null then raise exception'NOT_FOUND';end if;if p_idempotency_key is null or length(p_idempotency_key)not between 1 and 200 then raise exception'VALIDATION_ERROR';end if;select propose_request into prior from finance_private.payout_destinations where proposed_by=p_actor_account_id and propose_idempotency_key=p_idempotency_key;return jsonb_build_object('tutor_id',tutor,'owner_account_id',p_actor_account_id,'prior_request',prior);end$$;
create function api.submit_payout_destination(p_destination_id uuid,p_channel text,p_encrypted_identifier jsonb,p_masked_identifier text,p_identifier_fingerprint text,p_payee_name text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=''as $$declare actor uuid:=app_private.require_actor();tutor uuid;ctx jsonb;request jsonb;begin perform app_private.require_role(actor,'tutor');select id into tutor from app_private.tutors where account_id=actor;if tutor is null then raise exception'NOT_FOUND';end if;request:=jsonb_build_object('p_destination_id',p_destination_id,'p_channel',p_channel,'p_encrypted_identifier',p_encrypted_identifier,'p_masked_identifier',p_masked_identifier,'p_identifier_fingerprint',p_identifier_fingerprint,'p_payee_name',p_payee_name,'p_idempotency_key',p_idempotency_key);ctx:=app_private.booking_begin(actor,'submit_payout_destination',request,p_idempotency_key);if ctx->'replay_result'<>'null'then return ctx->'replay_result';end if;perform 1 from app_private.tutors where id=tutor for update;if not exists(select 1 from finance_private.tutor_payout_settings where tutor_id=tutor and p_channel=any(enabled_channels))then raise exception'METHOD_DISABLED';end if;
 if p_destination_id is null or p_channel is null or p_channel not in('instapay','vodafone_cash')or p_encrypted_identifier->'v' is distinct from '1'::jsonb or not coalesce(app_private.calendar_envelope_valid(p_encrypted_identifier,p_encrypted_identifier->>'kid'),false)or p_masked_identifier is null or p_masked_identifier!~'^••••( [A-Za-z0-9]{4})?$'or p_identifier_fingerprint is null or p_identifier_fingerprint!~'^[a-f0-9]{64}$'or p_payee_name is null or length(btrim(p_payee_name))not between 1 and 200 then raise exception'VALIDATION_ERROR';end if;
 insert into finance_private.payout_destinations(id,tutor_id,owner_account_id,channel,encrypted_identifier,masked_identifier,identifier_fingerprint,ciphertext_digest,payee_name,proposed_by,propose_idempotency_key,propose_request)values(p_destination_id,tutor,actor,p_channel,p_encrypted_identifier,p_masked_identifier,p_identifier_fingerprint,app_private.catalog_hash(p_encrypted_identifier),btrim(p_payee_name),actor,p_idempotency_key,request);perform set_config('response.status','201',true);return app_private.booking_finish(ctx,p_destination_id,1,jsonb_build_object('destination_id',p_destination_id,'masked_identifier',p_masked_identifier,'verification_status','unverified'),'payout_destination_submitted',jsonb_build_object('tutor_id',tutor,'destination_id',p_destination_id));end$$;
create function app_private.read_payout_destination_for_server(p_actor_account_id uuid,p_auth_session_id uuid,p_destination_id uuid,p_purpose text,p_payout_attempt_id uuid default null,p_reason text default null)returns jsonb language plpgsql security definer set search_path=''as $$declare d finance_private.payout_destinations%rowtype;verified uuid;begin perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id,true);select *into d from finance_private.payout_destinations where id=p_destination_id;if d.id is null then raise exception'NOT_FOUND';end if;select id into verified from finance_private.payout_destination_versions where destination_id=d.id;
 if p_purpose='verify_candidate'then if p_payout_attempt_id is not null then raise exception'VALIDATION_ERROR';end if;elsif p_purpose='reveal_for_attempt'then if p_reason is null or length(btrim(p_reason))not between 1 and 2000 or not exists(select 1 from finance_private.payout_attempts p join finance_private.payout_destination_versions v on v.id=p.destination_version_id where p.id=p_payout_attempt_id and v.destination_id=d.id and p.state in('pending','unknown'))then raise exception'FORBIDDEN';end if;else raise exception'VALIDATION_ERROR';end if;
 insert into app_private.audit_events(actor_account_id,command_id,action,aggregate_id,details)values(p_actor_account_id,gen_random_uuid(),'payout_identifier_accessed',d.id,jsonb_build_object('purpose',p_purpose,'attempt_id',p_payout_attempt_id,'reason',p_reason));return jsonb_build_object('destination_id',d.id,'tutor_id',d.tutor_id,'owner_account_id',d.owner_account_id,'channel',d.channel,'identifier_version',1,'version',d.version,'encrypted_identifier',d.encrypted_identifier,'ciphertext_digest',d.ciphertext_digest,'masked_identifier',d.masked_identifier,'identifier_fingerprint',d.identifier_fingerprint,'verification_status',d.verification_status,'destination_version_id',verified);end$$;
create function app_private.issue_payout_destination_validation_artifact(p_actor_account_id uuid,p_auth_session_id uuid,p_destination_id uuid,p_destination_version integer,p_ciphertext_digest text,p_masked_identifier text,p_identifier_fingerprint text,p_purpose text,p_approval_request jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare d finance_private.payout_destinations%rowtype;a finance_private.payout_destination_artifacts%rowtype;prior app_private.command_results%rowtype;hash text;begin perform app_private.payment_server_actor(p_actor_account_id,p_auth_session_id,true);select *into d from finance_private.payout_destinations where id=p_destination_id;if d.id is null then raise exception'NOT_FOUND';end if;
 if p_purpose is distinct from'verify_payout_destination'or jsonb_typeof(p_approval_request)is distinct from'object'or p_approval_request-array['destination_id','expected_version','evidence_file_id','decision','reason','idempotency_key']<>'{}'or not(p_approval_request ?& array['destination_id','expected_version','evidence_file_id','decision','reason','idempotency_key'])or jsonb_typeof(p_approval_request->'expected_version')is distinct from'number'or exists(select 1 from jsonb_each(p_approval_request)x where x.key<>'expected_version'and jsonb_typeof(x.value)<>'string')or p_approval_request->>'destination_id'is distinct from d.id::text or p_approval_request->>'decision'not in('verified','rejected')or length(btrim(coalesce(p_approval_request->>'reason','')))not between 1 and 2000 or length(coalesce(p_approval_request->>'idempotency_key',''))not between 1 and 200 then raise exception'VALIDATION_ERROR';end if;hash:=app_private.catalog_hash(p_approval_request);
 select *into prior from app_private.command_results where actor_account_id=p_actor_account_id and command_name='verify_payout_destination'and idempotency_key=p_approval_request->>'idempotency_key';if prior.id is not null then select *into a from finance_private.payout_destination_artifacts where consumed_command_id=prior.id and actor_account_id=p_actor_account_id and destination_id=d.id and approval_request_hash=hash;if a.id is null then raise exception'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('validation_artifact_id',a.id,'approval_request_hash',a.approval_request_hash,'expires_at',a.expires_at);end if;
 if d.version is distinct from p_destination_version or(p_approval_request->>'expected_version')::int is distinct from d.version then raise exception'VERSION_CONFLICT';end if;if d.ciphertext_digest is distinct from p_ciphertext_digest or d.masked_identifier is distinct from p_masked_identifier or d.identifier_fingerprint is distinct from p_identifier_fingerprint or d.verification_status<>'unverified'then raise exception'VALIDATION_ERROR';end if;
 insert into finance_private.payout_destination_artifacts(actor_account_id,auth_session_id,destination_id,destination_version,ciphertext_digest,approval_request,approval_request_hash,expires_at)values(p_actor_account_id,p_auth_session_id,d.id,d.version,d.ciphertext_digest,p_approval_request,hash,now()+interval'5 minutes')returning *into a;return jsonb_build_object('validation_artifact_id',a.id,'approval_request_hash',a.approval_request_hash,'expires_at',a.expires_at);end$$;
create function api.verify_payout_destination(p_destination_id uuid,p_evidence_file_id uuid,p_decision text,p_reason text,p_validation_artifact_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=''as $$declare actor uuid:=app_private.require_actor();session uuid:=(current_setting('request.jwt.claims',true)::jsonb->>'session_id')::uuid;d finance_private.payout_destinations%rowtype;a finance_private.payout_destination_artifacts%rowtype;ctx jsonb;request jsonb;verified uuid;begin perform app_private.require_role(actor,'admin');select *into d from finance_private.payout_destinations where id=p_destination_id;if d.id is null then raise exception'NOT_FOUND';end if;request:=jsonb_build_object('destination_id',p_destination_id,'expected_version',p_expected_version,'evidence_file_id',p_evidence_file_id,'decision',p_decision,'reason',p_reason,'idempotency_key',p_idempotency_key);ctx:=app_private.booking_begin(actor,'verify_payout_destination',request||jsonb_build_object('validation_artifact_id',p_validation_artifact_id),p_idempotency_key);if ctx->'replay_result'<>'null'then return ctx->'replay_result';end if;
 perform 1 from app_private.tutors where id=d.tutor_id for update;select *into d from finance_private.payout_destinations where id=p_destination_id for update;select *into a from finance_private.payout_destination_artifacts where id=p_validation_artifact_id for update;if d.version is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;if a.id is null or a.actor_account_id<>actor or a.auth_session_id<>session or a.destination_id<>d.id or a.destination_version<>d.version or a.expires_at<=now()or a.consumed_at is not null or a.ciphertext_digest<>d.ciphertext_digest or a.approval_request_hash<>app_private.catalog_hash(request)then raise exception'FORBIDDEN';end if;if p_decision is null or p_decision not in('verified','rejected')or p_reason is null or length(btrim(p_reason))not between 1 and 2000 or d.verification_status<>'unverified'then raise exception'VALIDATION_ERROR';end if;
 perform app_private.payment_assert_file(p_evidence_file_id,'payout_destination_verification','payout_destination',d.id);if p_decision='verified'then insert into finance_private.payout_destination_versions(destination_id,tutor_id,owner_account_id,channel,encrypted_identifier,masked_identifier,identifier_fingerprint,ciphertext_digest,evidence_file_id,verified_by,validation_artifact_id)values(d.id,d.tutor_id,d.owner_account_id,d.channel,d.encrypted_identifier,d.masked_identifier,d.identifier_fingerprint,d.ciphertext_digest,p_evidence_file_id,actor,a.id)returning id into verified;end if;update finance_private.payout_destination_artifacts set consumed_at=now(),consumed_command_id=(ctx->>'command_id')::uuid where id=a.id;update finance_private.payout_destinations set verification_status=p_decision,version=d.version+1 where id=d.id;return app_private.booking_finish(ctx,d.id,d.version+1,jsonb_build_object('destination_version_id',verified,'verification_status',p_decision),'payout_destination_verified',jsonb_build_object('tutor_id',d.tutor_id,'destination_id',d.id));end$$;

create function app_private.payroll_assert_destination(p_version uuid,p_tutor uuid)returns finance_private.payout_destination_versions language plpgsql security definer set search_path=''as $$declare d finance_private.payout_destination_versions%rowtype;owner uuid;begin select *into d from finance_private.payout_destination_versions where id=p_version;if d.id is null or d.tutor_id<>p_tutor then raise exception'DESTINATION_UNVERIFIED';end if;select account_id into owner from app_private.tutors where id=p_tutor;perform app_private.require_role(owner,'tutor');perform app_private.require_role(d.verified_by,'admin');if not app_private.payment_verified_account(owner)or not app_private.payment_verified_account(d.verified_by)then raise exception'FORBIDDEN';end if;if not exists(select 1 from finance_private.tutor_payout_settings where tutor_id=p_tutor and d.channel=any(enabled_channels))then raise exception'METHOD_DISABLED';end if;if d.destination_id is distinct from(select id from finance_private.payout_destinations where tutor_id=p_tutor and channel=d.channel order by created_at desc,id desc limit 1)then raise exception'DESTINATION_UNVERIFIED';end if;return d;end$$;
create function app_private.payroll_command(p_name text,p_input jsonb,p_key text)returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare actor uuid:=app_private.require_actor();ctx jsonb;p finance_private.payout_attempts%rowtype;d finance_private.payout_destination_versions%rowtype;tutor uuid;owner uuid;allocations jsonb;allocation jsonb;balance jsonb;total numeric:=0;attempt uuid;receiving uuid;outcome text;effective timestamptz;posting uuid;reference text;evidence uuid;reverse_id uuid;amount bigint;remaining bigint;returned bigint;row record;piece bigint;residual bigint;statement jsonb;source finance_private.payout_outcomes%rowtype;begin
 perform app_private.require_role(actor,'admin');if p_name='authorize_payout'then tutor:=(p_input->>'tutor_id')::uuid;else select *into p from finance_private.payout_attempts where id=(p_input->>'payout_attempt_id')::uuid;if p.id is null then raise exception'NOT_FOUND';end if;tutor:=p.tutor_id;end if;perform app_private.payroll_assert_scope(actor,tutor);ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'then return ctx->'replay_result';end if;
 perform 1 from app_private.tutors where id=tutor for update;perform 1 from finance_private.tutor_earnings where tutor_id=tutor order by id for update;if p.id is not null then select *into p from finance_private.payout_attempts where id=p.id for update;if(p_input->>'expected_version')::integer is distinct from p.version then raise exception'VERSION_CONFLICT';end if;end if;
 if p_name in('authorize_payout','retry_payout')then d:=app_private.payroll_assert_destination((p_input->>'destination_version_id')::uuid,tutor);if p_name='retry_payout'then if p.state<>'failed'or exists(select 1 from finance_private.payout_attempts where retry_of_attempt_id=p.id)then raise exception'STATE_CONFLICT';end if;select jsonb_agg(jsonb_build_object('earning_id',earning_id,'amount_minor',amount_minor)order by earning_id)into allocations from finance_private.payout_allocations where payout_attempt_id=p.id;else allocations:=p_input->'allocations';end if;
  if jsonb_typeof(allocations)is distinct from'array'or jsonb_array_length(allocations)not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;for allocation in select value from jsonb_array_elements(allocations)loop if jsonb_typeof(allocation)is distinct from'object'or allocation-array['earning_id','amount_minor']<>'{}'or not(allocation ?& array['earning_id','amount_minor'])or jsonb_typeof(allocation->'earning_id')is distinct from'string'then raise exception'VALIDATION_ERROR';end if;amount:=app_private.package_safe_integer(allocation->'amount_minor',1);if not exists(select 1 from finance_private.tutor_earnings where id=(allocation->>'earning_id')::uuid and tutor_id=tutor)then raise exception'NOT_FOUND';end if;balance:=finance_private.payroll_earning_balance((allocation->>'earning_id')::uuid);if amount>(balance->>'available_minor')::bigint then raise exception'INSUFFICIENT_PAYABLE';end if;total:=total+amount;end loop;
  if(select count(distinct value->>'earning_id')from jsonb_array_elements(allocations))<>jsonb_array_length(allocations)then raise exception'VALIDATION_ERROR';end if;statement:=finance_private.payroll_statement(tutor);if total>(statement->>'available_minor')::bigint then raise exception'INSUFFICIENT_PAYABLE';end if;total:=finance_private.finance_safe_total(total);
  insert into finance_private.payout_attempts(tutor_id,destination_version_id,amount_minor,retry_of_attempt_id,authorized_by,command_id)values(tutor,d.id,total,case when p_name='retry_payout'then p.id end,actor,(ctx->>'command_id')::uuid)returning id into attempt;insert into finance_private.payout_allocations(payout_attempt_id,earning_id,amount_minor)select attempt,(value->>'earning_id')::uuid,(value->>'amount_minor')::bigint from jsonb_array_elements(allocations);perform set_config('response.status','201',true);return app_private.booking_finish(ctx,attempt,1,jsonb_build_object('payout_attempt_id',attempt,'state','pending','reserved_minor',total),'payout_authorized',jsonb_build_object('tutor_id',tutor,'payout_attempt_id',attempt));
 end if;
 reference:=p_input->>'external_reference';evidence:=(p_input->>'evidence_file_id')::uuid;receiving:=(p_input->>'receiving_account_id')::uuid;if reference is null or length(btrim(reference))not between 1 and 200 or evidence is null then raise exception'VALIDATION_ERROR';end if;
 if p_name='reconcile_payout'then outcome:=p_input->>'outcome';effective:=(p_input->>'settled_at')::timestamptz;if p.state not in('pending','unknown')then raise exception'STATE_CONFLICT';end if;if outcome is null or outcome not in('settled','failed','unknown')or(outcome='settled'and(effective is null or receiving is null))or(outcome<>'settled'and effective is not null)then raise exception'VALIDATION_ERROR';end if;perform app_private.payment_assert_file(evidence,'payout_reconciliation','payout_attempt',p.id);
  if outcome='settled'then if not isfinite(effective)or effective>now()or effective<p.created_at-interval'5 seconds'then raise exception'INVALID_TIME';end if;perform 1 from finance_private.receiving_accounts where id=receiving and enabled and current_version_id is not null for share;if not found then raise exception'FORBIDDEN';end if;insert into finance_private.outgoing_cash_references(receiving_account_id,external_reference,source_type,source_id)values(receiving,reference,'payout',p.id);posting:=finance_private.finance_post_balanced('payout:'||p.id,'payout_settled',p.id,'EGP',effective,jsonb_build_array(jsonb_build_object('account_code','tutor_payable','signed_minor',p.amount_minor),jsonb_build_object('account_code','channel_cash','receiving_account_id',receiving,'signed_minor',-p.amount_minor)),ctx);end if;
  insert into finance_private.payout_outcomes(payout_attempt_id,outcome,receiving_account_id,external_reference,evidence_file_id,settled_at,ledger_transaction_id,actor_account_id,command_id)values(p.id,outcome,receiving,reference,evidence,effective,posting,actor,(ctx->>'command_id')::uuid);update finance_private.payout_attempts set state=outcome,version=p.version+1 where id=p.id;statement:=finance_private.payroll_statement(tutor);return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('state',outcome,'owed_minor',statement->'owed_minor','available_minor',statement->'available_minor'),'payout_'||outcome,jsonb_build_object('tutor_id',tutor,'payout_attempt_id',p.id));
 elsif p_name='record_payout_reversal'then if p.state<>'settled'then raise exception'STATE_CONFLICT';end if;amount:=app_private.package_safe_integer(p_input->'amount_minor',1);effective:=(p_input->>'effective_at')::timestamptz;select *into source from finance_private.payout_outcomes where payout_attempt_id=p.id and outcome='settled';select coalesce(sum(r.amount_minor),0)into returned from finance_private.payout_reversals r where r.payout_attempt_id=p.id;if amount>p.amount_minor-returned then raise exception'VALIDATION_ERROR';end if;if receiving is distinct from source.receiving_account_id or effective is null or not isfinite(effective)or effective>now()or effective<source.settled_at or p_input->>'reason'is null or length(btrim(p_input->>'reason'))not between 1 and 2000 then raise exception'INVALID_TIME';end if;perform app_private.payment_assert_file(evidence,'payout_reversal','payout_attempt',p.id);reverse_id:=gen_random_uuid();posting:=finance_private.finance_post_balanced('payout-reversal:'||reverse_id,'payout_reversal',reverse_id,'EGP',effective,jsonb_build_array(jsonb_build_object('account_code','channel_cash','receiving_account_id',receiving,'signed_minor',amount),jsonb_build_object('account_code','tutor_payable','signed_minor',-amount)),ctx);
  insert into finance_private.payout_reversals(id,payout_attempt_id,amount_minor,receiving_account_id,external_reference,evidence_file_id,effective_at,reason,ledger_transaction_id,actor_account_id,command_id)values(reverse_id,p.id,amount,receiving,reference,evidence,effective,p_input->>'reason',posting,actor,(ctx->>'command_id')::uuid);remaining:=p.amount_minor-returned;
  select amount-coalesce(sum(floor(amount::numeric*(a.amount_minor-coalesce((select sum(r.amount_minor)from finance_private.payout_reversal_allocations r where r.payout_allocation_id=a.id),0))/remaining)),0)::bigint into residual from finance_private.payout_allocations a where a.payout_attempt_id=p.id;
  for row in select a.id,a.amount_minor-coalesce((select sum(r.amount_minor)from finance_private.payout_reversal_allocations r where r.payout_allocation_id=a.id),0) net from finance_private.payout_allocations a where a.payout_attempt_id=p.id order by mod(amount::numeric*(a.amount_minor-coalesce((select sum(r.amount_minor)from finance_private.payout_reversal_allocations r where r.payout_allocation_id=a.id),0)),remaining)desc,a.id loop piece:=floor(amount::numeric*row.net/remaining);if residual>0 then piece:=piece+1;residual:=residual-1;end if;if piece>0 then insert into finance_private.payout_reversal_allocations values(reverse_id,row.id,piece);end if;end loop;
  update finance_private.payout_attempts set state=case when returned+amount=p.amount_minor then'reversed'else'settled'end,version=p.version+1 where id=p.id;statement:=finance_private.payroll_statement(tutor);return app_private.booking_finish(ctx,p.id,p.version+1,jsonb_build_object('reversal_id',reverse_id,'state',case when returned+amount=p.amount_minor then'reversed'else'settled'end,'owed_minor',statement->'owed_minor','available_minor',statement->'available_minor'),'payout_reversed',jsonb_build_object('tutor_id',tutor,'payout_attempt_id',p.id,'reversal_id',reverse_id));
 end if;raise exception'VALIDATION_ERROR';exception when invalid_text_representation or datetime_field_overflow then raise exception'VALIDATION_ERROR';when unique_violation then raise exception'STATE_CONFLICT';end$$;
create function api.authorize_payout(p_tutor_id uuid,p_destination_version_id uuid,p_allocations jsonb,p_idempotency_key text)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_command('authorize_payout',jsonb_build_object('tutor_id',p_tutor_id,'destination_version_id',p_destination_version_id,'allocations',p_allocations),p_idempotency_key)$$;
create function api.retry_payout(p_payout_attempt_id uuid,p_destination_version_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_command('retry_payout',jsonb_build_object('payout_attempt_id',p_payout_attempt_id,'destination_version_id',p_destination_version_id,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.reconcile_payout(p_payout_attempt_id uuid,p_outcome text,p_receiving_account_id uuid,p_external_reference text,p_evidence_file_id uuid,p_settled_at timestamptz,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_command('reconcile_payout',jsonb_build_object('payout_attempt_id',p_payout_attempt_id,'outcome',p_outcome,'receiving_account_id',p_receiving_account_id,'external_reference',p_external_reference,'evidence_file_id',p_evidence_file_id,'settled_at',p_settled_at,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.record_payout_reversal(p_payout_attempt_id uuid,p_amount_minor bigint,p_receiving_account_id uuid,p_external_reference text,p_evidence_file_id uuid,p_effective_at timestamptz,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language sql security definer set search_path=''as $$select app_private.payroll_command('record_payout_reversal',jsonb_build_object('payout_attempt_id',p_payout_attempt_id,'amount_minor',p_amount_minor,'receiving_account_id',p_receiving_account_id,'external_reference',p_external_reference,'evidence_file_id',p_evidence_file_id,'effective_at',p_effective_at,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;

alter function app_private.file_resolve_target(uuid,text,text,uuid)rename to file_resolve_target_pre_payroll;
create function app_private.file_resolve_target(p_actor uuid,p_purpose text,p_action text,p_target uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare internal text;parent text;begin if p_purpose='review_evidence'and p_action in('verify_payout_destination','reconcile_payout','record_payout_reversal')then perform app_private.require_role(p_actor,'admin');if p_action='verify_payout_destination'then if not exists(select 1 from finance_private.payout_destinations where id=p_target)then raise exception'NOT_FOUND';end if;internal:='payout_destination_verification';parent:='payout_destination';else if not exists(select 1 from finance_private.payout_attempts where id=p_target)then raise exception'NOT_FOUND';end if;internal:=case p_action when'reconcile_payout'then'payout_reconciliation'else'payout_reversal'end;parent:='payout_attempt';end if;return jsonb_build_object('internal_purpose',internal,'parent_type',parent,'parent_id',p_target,'learner_id',null,'charge_id',null);end if;return app_private.file_resolve_target_pre_payroll(p_actor,p_purpose,p_action,p_target);end$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname in('app_private','finance_private')and(p.proname like'payroll_%'or p.proname in('prepare_payout_destination','read_payout_destination_for_server','issue_payout_destination_validation_artifact','file_resolve_target')))or(n.nspname='api'and p.proname in('get_tutor_statement','list_tutor_earnings','list_payout_destinations','list_payouts','list_payout_tutors','set_tutor_payout_methods','submit_payout_destination','verify_payout_destination','authorize_payout','retry_payout','reconcile_payout','record_payout_reversal'))loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('prepare_payout_destination','read_payout_destination_for_server','issue_payout_destination_validation_artifact')then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';
